out=[[2,2,2,1,1,1,2,0],[2,1,1,1,3,1,2,0],[2,1,3,3,3,1,2,0],[2,1,3,0,3,1,2,0],[2,1,3,3,3,1,2,0],[2,1,1,1,1,1,2,0],[2,2,2,2,2,2,2,0],[0,0,0,0,0,0,0,0]]
from collections import deque
def transform(g):
    h,w=len(g),len(g[0])
    # exterior zeros
    ext=set()
    q=deque((i,j) for i in range(h) for j in range(w) if g[i][j]==0 and (i in(0,h-1) or j in(0,w-1)))
    for c in q: ext.add(c)
