from collections import deque
def transform(g):
    h,w=len(g),len(g[0])
    # 4-connected exterior flood over zeros
    ext=set()
    q=deque((i,j) for i in range(h) for j in range(w) if g[i][j]==0 and (i in(0,h-1) or j in(0,w-1)))
    for c in q: ext.add(c)
    while q:
        i,j=q.popleft()
        for di,dj in((1,0),(-1,0),(0,1),(0,-1)):
            ni,nj=i+di,j+dj
            if 0<=ni<h and 0<=nj<w and g[ni][nj]==0 and (ni,nj) not in ext:
                ext.add((ni,nj)); q.append((ni,nj))
    interior={(i,j) for i in range(h) for j in range(w) if g[i][j]==0 and (i,j) not in ext}
    def walltouches(p):
        i,j=p
        return any(0<=i+di<h and 0<=j+dj<w and g[i+di][j+dj]==1 and any(0<=i+di+ei<h and 0<=j+dj+ej<w and g[i+di+ei][j+dj+ej]==0 and (i+di+ei,j+dj+ej) in interior for ei in(-1,0,1) for ej in(-1,0,1)) for di in(-1,0,1) for dj in(-1,0,1))
    res=[row[:] for row in g]
    for i in range(h):
        for j in range(w):
            if g[i][j]==0:
                adj=any(0<=i+di<h and 0<=j+dj<w and g[i+di][j+dj]==1 for di in(-1,0,1) for dj in(-1,0,1))
                if (i,j) in interior and adj: res[i][j]=3
                elif (i,j) not in interior and adj and walltouches((i,j)): res[i][j]=2
    return res
